vocab_size = tok.vocab_size
prohibited_tokens = tok.all_special_ids
all_tokens = np.arange(vocab_size)
allowed_tokens = np.array(list(set(all_tokens) - set(prohibited_tokens)))

# random offset like vLLM does
rng = np.random.default_rng(seed=0)
offset = rng.integers(0, vocab_size)
input_len = 512
index = 0 # first request

inner_seq = allowed_tokens[
    (offset + index + np.arange(input_len)) % len(allowed_tokens)
].tolist()

prompt = tok.decode(inner_seq)
print(f"Token count: {len(tok(prompt).input_ids)}")
print(repr(prompt))
